package webui

import (
	"bytes"
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"net/http"
	"strings"
	"time"
)

// dist is generated by the frontend build before Go compilation.
//
//go:embed dist
var assets embed.FS

func serveAsset(w http.ResponseWriter, r *http.Request) {
	name := strings.TrimPrefix(r.URL.Path, "/")
	// Only known application entry points receive the SPA document. Missing
	// assets, unknown API paths and private filesystem-looking paths stay 404.
	if name == "" || name == "sources" || name == "settings" || name == "activity" {
		name = "index.html"
	}
	for _, component := range strings.Split(name, "/") {
		if strings.HasPrefix(component, ".") || component == "" {
			problem(w, http.StatusNotFound)
			return
		}
	}
	data, err := assets.ReadFile("dist/" + name)
	if err != nil {
		problem(w, http.StatusNotFound)
		return
	}
	hash := sha256.Sum256(data)
	w.Header().Set("ETag", `"`+hex.EncodeToString(hash[:])+`"`)
	http.ServeContent(w, r, name, time.Time{}, bytes.NewReader(data))
}
